---------------------
---- KEYBINDINGS ----
---------------------

local mainMod = "SUPER"

hl.bind(mainMod .. " + RETURN", hl.dsp.exec_cmd(terminal))
hl.bind(mainMod .. " + Q",      hl.dsp.window.close())
-- hl.bind(mainMod .. " + M",   hl.dsp.exit())
hl.bind(mainMod .. " + E",      hl.dsp.exec_cmd(fileManager))
hl.bind(mainMod .. " + V",      hl.dsp.exec_cmd("cliphist list | " .. menu .. " --dmenu | cliphist decode | wl-copy"))
hl.bind(mainMod .. " + SPACE",  hl.dsp.exec_cmd(menu .. " --show drun"))
hl.bind(mainMod .. " + P",      hl.dsp.layout("togglesplit")) -- dwindle
hl.bind(mainMod .. " + W",      hl.dsp.exec_cmd("pkill waybar; waybar &"))
hl.bind(mainMod .. " + SHIFT + L", hl.dsp.exec_cmd("hyprlock"))
-- fullscreen with waybar: maximize internally, leave the client's fullscreen state alone.
-- Same as hyprlang's `fullscreenstate 1`, which resolved the omitted client mode to the current one.
hl.bind(mainMod .. " + F", function()
    local w = hl.get_active_window()
    if not w then
        return
    end
    hl.dispatch(hl.dsp.window.fullscreen_state({
        internal = 1,
        client   = w.fullscreen_client,
        action   = w.fullscreen == 1 and "unset" or "set",
    }))
end)
hl.bind(mainMod .. " + SHIFT + F", hl.dsp.window.fullscreen({ mode = "fullscreen", action = "toggle" })) -- true fullscreen
hl.bind(mainMod .. " + SHIFT + C", hl.dsp.exec_cmd('grim -g "$(slurp)" -t ppm - | satty --filename -'))

-- Move focus
hl.bind(mainMod .. " + H", hl.dsp.focus({ direction = "left" }))
hl.bind(mainMod .. " + L", hl.dsp.focus({ direction = "right" }))
hl.bind(mainMod .. " + J", hl.dsp.focus({ direction = "up" }))
hl.bind(mainMod .. " + K", hl.dsp.focus({ direction = "down" }))

-- Set split direction
hl.bind(mainMod .. " + SHIFT + H", hl.dsp.layout("preselect d"))
hl.bind(mainMod .. " + SHIFT + V", hl.dsp.layout("preselect r"))

-- Switch workspaces with mainMod + [0-9]
-- Move active window to a workspace with mainMod + SHIFT + [0-9]
for i = 1, 10 do
    local key = i % 10 -- 10 maps to key 0
    hl.bind(mainMod .. " + " .. key,         hl.dsp.focus({ workspace = i }))
    hl.bind(mainMod .. " + SHIFT + " .. key, hl.dsp.window.move({ workspace = i }))
end

-- Special workspace (scratchpad)
hl.bind(mainMod .. " + S",         hl.dsp.workspace.toggle_special("magic"))
hl.bind(mainMod .. " + SHIFT + S", hl.dsp.window.move({ workspace = "special:magic" }))

-- Scroll through existing workspaces with mainMod + scroll
hl.bind(mainMod .. " + mouse_down", hl.dsp.focus({ workspace = "e+1" }))
hl.bind(mainMod .. " + mouse_up",   hl.dsp.focus({ workspace = "e-1" }))

-- Move/resize windows with mainMod + LMB/RMB and dragging
hl.bind(mainMod .. " + mouse:272", hl.dsp.window.drag())
hl.bind(mainMod .. " + mouse:273", hl.dsp.window.resize())

-- Laptop multimedia keys for volume and LCD brightness
hl.bind("XF86AudioRaiseVolume",  hl.dsp.exec_cmd("wpctl set-volume -l 1 @DEFAULT_AUDIO_SINK@ 5%+"), { locked = true, repeating = true })
hl.bind("XF86AudioLowerVolume",  hl.dsp.exec_cmd("wpctl set-volume @DEFAULT_AUDIO_SINK@ 5%-"),      { locked = true, repeating = true })
hl.bind("XF86AudioMute",         hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SINK@ toggle"),     { locked = true, repeating = true })
hl.bind("XF86AudioMicMute",      hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SOURCE@ toggle"),   { locked = true, repeating = true })
hl.bind("XF86MonBrightnessUp",   hl.dsp.exec_cmd("brightnessctl -e4 -n2 set 5%+"),                  { locked = true, repeating = true })
hl.bind("XF86MonBrightnessDown", hl.dsp.exec_cmd("brightnessctl -e4 -n2 set 5%-"),                  { locked = true, repeating = true })

-- Requires playerctl
hl.bind("XF86AudioNext",  hl.dsp.exec_cmd("playerctl next"),       { locked = true })
hl.bind("XF86AudioPause", hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
hl.bind("XF86AudioPlay",  hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
hl.bind("XF86AudioPrev",  hl.dsp.exec_cmd("playerctl previous"),   { locked = true })

-- Resize windows
hl.bind(mainMod .. " + R", hl.dsp.submap("resizer"))
hl.define_submap("resizer", function()
    hl.bind("H", hl.dsp.window.resize({ x = -10, y = 0,   relative = true }), { repeating = true })
    hl.bind("J", hl.dsp.window.resize({ x = 0,   y = 10,  relative = true }), { repeating = true })
    hl.bind("K", hl.dsp.window.resize({ x = 0,   y = -10, relative = true }), { repeating = true })
    hl.bind("L", hl.dsp.window.resize({ x = 10,  y = 0,   relative = true }), { repeating = true })
    hl.bind("escape", hl.dsp.submap("reset"))
end)

-- Alt+Tab
-- The scripts in scripts/alttab toggle these via `hyprctl eval 'alttab_binds(...)'`.
local alttabDir = os.getenv("HOME") .. "/.config/hypr/scripts/alttab"
local alttabOpen = {
    hl.bind("ALT + TAB",         hl.dsp.exec_cmd(alttabDir .. "/enable.sh 'down'")),
    hl.bind("ALT + SHIFT + TAB", hl.dsp.exec_cmd(alttabDir .. "/enable.sh 'up'")),
}
function alttab_binds(enabled)
    for _, b in ipairs(alttabOpen) do
        b:set_enabled(enabled)
    end
end

-- Does what disable.sh does, but synchronously so it finishes before the key is
-- sent, like the old `exec, disable.sh ; hyprctl dispatch sendshortcut ...` did.
local function alttabFinish(key)
    return function()
        if hl.get_current_submap() ~= "alttab" then
            return
        end
        hl.config({ animations = { enabled = true } })
        alttab_binds(true)
        -- Inside a bind, send_shortcut only mirrors the triggering key's state (just
        -- a key-up when fired on Alt release), so send an explicit down + up.
        hl.dispatch(hl.dsp.send_key_state({ mods = "", key = key, state = "down", window = "class:alttab" }))
        hl.dispatch(hl.dsp.send_key_state({ mods = "", key = key, state = "up",   window = "class:alttab" }))
    end
end

hl.define_submap("alttab", function()
    hl.bind("ALT + TAB",         hl.dsp.send_shortcut({ mods = "",      key = "tab", window = "class:alttab" }))
    hl.bind("ALT + SHIFT + TAB", hl.dsp.send_shortcut({ mods = "shift", key = "tab", window = "class:alttab" }))

    -- Alt was pressed before this submap was entered, and a release only matches binds
    -- from the submap active at press time, so these must be submap_universal.
    -- alttabFinish() ignores them outside the alttab submap.
    hl.bind("ALT + ALT_L",          alttabFinish("return"), { release = true, transparent = true, submap_universal = true })
    hl.bind("ALT + SHIFT + ALT_L",  alttabFinish("return"), { release = true, transparent = true, submap_universal = true })
    hl.bind("ALT + Return",         alttabFinish("return"))
    hl.bind("ALT + SHIFT + Return", alttabFinish("return"))
    hl.bind("ALT + escape",         alttabFinish("escape"))
    hl.bind("ALT + SHIFT + escape", alttabFinish("escape"))
end)


